-- Run this setup once in an Oracle schema where these tables do not already exist.
-- order_id is generated by a sequence-trigger pair (not an identity column).

CREATE TABLE customers (
    customer_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_name VARCHAR2(100) NOT NULL,
    phone VARCHAR2(20)
);

CREATE TABLE menu_items (
    menu_item_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    item_name VARCHAR2(100) NOT NULL,
    price NUMBER(10, 2) NOT NULL CHECK (price > 0)
);

CREATE TABLE food_orders (
    order_id NUMBER PRIMARY KEY,
    customer_id NUMBER NOT NULL REFERENCES customers(customer_id),
    order_date TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    status VARCHAR2(20) DEFAULT 'PLACED' NOT NULL
        CHECK (status IN ('PLACED', 'PREPARING', 'DELIVERED', 'CANCELLED'))
);

CREATE TABLE order_items (
    order_id NUMBER NOT NULL REFERENCES food_orders(order_id),
    menu_item_id NUMBER NOT NULL REFERENCES menu_items(menu_item_id),
    quantity NUMBER NOT NULL CHECK (quantity > 0),
    unit_price NUMBER(10, 2) NOT NULL CHECK (unit_price > 0),
    PRIMARY KEY (order_id, menu_item_id)
);

CREATE SEQUENCE food_orders_seq
    START WITH 10000
    INCREMENT BY 1
    MAXVALUE 99999
    NOCYCLE;

CREATE OR REPLACE TRIGGER food_orders_bi
BEFORE INSERT ON food_orders
FOR EACH ROW
WHEN (NEW.order_id IS NULL)
BEGIN
    :NEW.order_id := food_orders_seq.NEXTVAL;
END;
/

CREATE OR REPLACE PROCEDURE place_order (
    p_customer_id IN NUMBER,
    p_order_id    OUT NUMBER
)
AS
BEGIN
    INSERT INTO food_orders (customer_id)
    VALUES (p_customer_id)
    RETURNING order_id INTO p_order_id;
END;
/

CREATE OR REPLACE PROCEDURE add_order_item (
    p_order_id    IN NUMBER,
    p_menu_item_id IN NUMBER,
    p_quantity    IN NUMBER
)
AS
    v_price menu_items.price%TYPE;
BEGIN
    IF p_quantity <= 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'Quantity must be greater than zero.');
    END IF;

    SELECT price
    INTO v_price
    FROM menu_items
    WHERE menu_item_id = p_menu_item_id;

    INSERT INTO order_items (order_id, menu_item_id, quantity, unit_price)
    VALUES (p_order_id, p_menu_item_id, p_quantity, v_price);
END;
/

-- Add menu items and ten customers, each with two separate orders.
DECLARE
    v_biryani NUMBER;
    v_burger  NUMBER;
    v_pizza   NUMBER;
    v_dosa    NUMBER;
    v_roll    NUMBER;
    v_juice   NUMBER;

    v_customer_id NUMBER;
    v_first_item  PLS_INTEGER;
    v_second_item PLS_INTEGER;

    TYPE item_id_list IS VARRAY(6) OF NUMBER;
    v_items item_id_list;

    TYPE name_list IS VARRAY(10) OF VARCHAR2(100);
    v_names name_list := name_list(
        'Priya Sharma',
        'Arjun Mehta',
        'Sneha Kulkarni',
        'Kabir Joshi',
        'Anaya Rao',
        'Rohan Desai',
        'Isha Nair',
        'Vikram Shah',
        'Meera Patil',
        'Dev Malhotra'
    );

    PROCEDURE create_sample_order (
        p_customer_id IN NUMBER,
        p_item1_id    IN NUMBER,
        p_quantity1   IN NUMBER,
        p_item2_id    IN NUMBER,
        p_quantity2   IN NUMBER,
        p_status      IN VARCHAR2
    )
    AS
        v_order_id NUMBER;
    BEGIN
        place_order(p_customer_id, v_order_id);
        UPDATE food_orders
        SET status = p_status
        WHERE order_id = v_order_id;

        add_order_item(v_order_id, p_item1_id, p_quantity1);
        add_order_item(v_order_id, p_item2_id, p_quantity2);
    END;
BEGIN
    INSERT INTO menu_items (item_name, price)
    VALUES ('Veg Biryani', 190)
    RETURNING menu_item_id INTO v_biryani;

    INSERT INTO menu_items (item_name, price)
    VALUES ('Veg Burger', 120)
    RETURNING menu_item_id INTO v_burger;

    INSERT INTO menu_items (item_name, price)
    VALUES ('Paneer Pizza', 250)
    RETURNING menu_item_id INTO v_pizza;

    INSERT INTO menu_items (item_name, price)
    VALUES ('Masala Dosa', 140)
    RETURNING menu_item_id INTO v_dosa;

    INSERT INTO menu_items (item_name, price)
    VALUES ('Paneer Roll', 160)
    RETURNING menu_item_id INTO v_roll;

    INSERT INTO menu_items (item_name, price)
    VALUES ('Mango Juice', 80)
    RETURNING menu_item_id INTO v_juice;

    v_items := item_id_list(
        v_biryani, v_burger, v_pizza, v_dosa, v_roll, v_juice
    );

    FOR i IN 1..v_names.COUNT LOOP
        INSERT INTO customers (customer_name, phone)
        VALUES (v_names(i), '987650' || LPAD(TO_CHAR(i), 4, '0'))
        RETURNING customer_id INTO v_customer_id;

        v_first_item := MOD(i - 1, 6) + 1;
        v_second_item := MOD(i + 1, 6) + 1;
        create_sample_order(
            v_customer_id,
            v_items(v_first_item),
            1 + MOD(i, 2),
            v_items(v_second_item),
            1,
            CASE MOD(i - 1, 4)
                WHEN 0 THEN 'PLACED'
                WHEN 1 THEN 'PREPARING'
                WHEN 2 THEN 'DELIVERED'
                ELSE 'CANCELLED'
            END
        );

        v_first_item := MOD(i + 1, 6) + 1;
        v_second_item := MOD(i + 3, 6) + 1;
        create_sample_order(
            v_customer_id,
            v_items(v_first_item),
            1,
            v_items(v_second_item),
            1 + MOD(i + 1, 2),
            CASE MOD(i, 4)
                WHEN 0 THEN 'PLACED'
                WHEN 1 THEN 'PREPARING'
                WHEN 2 THEN 'DELIVERED'
                ELSE 'CANCELLED'
            END
        );
    END LOOP;

    COMMIT;
END;
/

-- Optional: assign varied statuses to orders already in the table.
UPDATE food_orders
SET status = CASE MOD(order_id, 4)
    WHEN 0 THEN 'PLACED'
    WHEN 1 THEN 'PREPARING'
    WHEN 2 THEN 'DELIVERED'
    ELSE 'CANCELLED'
END;
COMMIT;

-- Display one row per order, listing all items and the order total.
SELECT
    c.customer_name,
    c.phone,
    o.order_id,
    o.order_date,
    o.status,
    LISTAGG(
        m.item_name || ' x' || oi.quantity || ' ('
            || TO_CHAR(oi.quantity * oi.unit_price, 'FM9999990.00') || ')',
        ', '
    ) WITHIN GROUP (ORDER BY m.item_name) AS ordered_items,
    SUM(oi.quantity * oi.unit_price) AS order_total
FROM customers c
JOIN food_orders o ON o.customer_id = c.customer_id
JOIN order_items oi ON oi.order_id = o.order_id
JOIN menu_items m ON m.menu_item_id = oi.menu_item_id
GROUP BY c.customer_name, c.phone, o.order_id, o.order_date, o.status
ORDER BY o.order_id;
